import subprocess
import os
import sys

def run_git(args, cwd=None, capture=True, check=False):
    cmd = ["git"] + args
    res = subprocess.run(cmd, cwd=cwd, capture_output=capture, text=True)
    if check and res.returncode != 0:
        raise RuntimeError(f"Git command failed: {' '.join(cmd)}\n{res.stderr}")
    return res

def git_out(args, cwd=None):
    res = run_git(args, cwd=cwd)
    if res.returncode != 0:
        return None
    return res.stdout.strip()

def get_repo_root(cwd=None):
    res = run_git(["rev-parse", "--show-toplevel"], cwd=cwd)
    if res.returncode != 0:
        return None
    return res.stdout.strip()

def get_current_branch(cwd=None):
    out = git_out(["symbolic-ref", "--short", "HEAD"], cwd=cwd)
    if out:
        return out
    # Detached HEAD
    out = git_out(["rev-parse", "--short", "HEAD"], cwd=cwd)
    return out

def get_head_oid(cwd=None):
    return git_out(["rev-parse", "HEAD"], cwd=cwd)

def commit_tree(tree_oid, parents=None, message="", author=None, committer=None, cwd=None):
    env = os.environ.copy()
    if author:
        env["GIT_AUTHOR_NAME"] = author.get("name", "")
        env["GIT_AUTHOR_EMAIL"] = author.get("email", "")
        if "date" in author:
            env["GIT_AUTHOR_DATE"] = author["date"]
    if committer:
        env["GIT_COMMITTER_NAME"] = committer.get("name", "")
        env["GIT_COMMITTER_EMAIL"] = committer.get("email", "")
        if "date" in committer:
            env["GIT_COMMITTER_DATE"] = committer["date"]

    args = ["commit-tree", tree_oid]
    if parents:
        for p in parents:
            args.extend(["-p", p])

    cmd = ["git"] + args
    res = subprocess.run(cmd, cwd=cwd, input=message, capture_output=True, text=True, env=env)
    if res.returncode != 0:
        raise RuntimeError(f"git commit-tree failed: {res.stderr}")
    return res.stdout.strip()

def write_tree_from_index(cwd=None):
    return git_out(["write-tree"], cwd=cwd)

def create_blob(content_bytes, cwd=None):
    cmd = ["git", "hash-object", "-w", "--stdin"]
    res = subprocess.run(cmd, cwd=cwd, input=content_bytes, capture_output=True)
    if res.returncode != 0:
        raise RuntimeError("hash-object failed")
    return res.stdout.decode().strip()

def create_tree(entries, cwd=None):
    # entries: list of (mode, type, oid, name)
    lines = [f"{mode} {type_} {oid}\t{name}" for mode, type_, oid, name in entries]
    input_str = "\n".join(lines) + "\n"
    cmd = ["git", "mktree"]
    res = subprocess.run(cmd, cwd=cwd, input=input_str, capture_output=True, text=True)
    if res.returncode != 0:
        raise RuntimeError(f"mktree failed: {res.stderr}")
    return res.stdout.strip()

def read_blob(oid, cwd=None):
    cmd = ["git", "cat-file", "-p", oid]
    res = subprocess.run(cmd, cwd=cwd, capture_output=True)
    if res.returncode != 0:
        return None
    return res.stdout

def cat_file_p(oid, cwd=None):
    return git_out(["cat-file", "-p", oid], cwd=cwd)

